/* @socom-skeleton stub Clear_Messages__12C2DMessage_QFv */
void C2DMessage_Q::Clear_Messages()
{
	/* 0x200920 (ReOpen_Unload1, CHUD::ReleaseHUD): every queued message leaves the list and
	 * is deleted (virtual deleting dtor) */
	iterator it = begin();

	while (it != end())
	{
		C2D* message = *it;
		it = erase(it);

		if (message != NULL)
			delete message;
	}
}

/* @socom-skeleton stub LastMessage__12C2DMessage_QFv */
char * C2DMessage_Q::LastMessage()
{
	/* 0x200890 (CZKit::PickupAmmo): the newest message's whole text, else "" */
	C2DMessageString *last = NULL;

	for (iterator it = begin(); it != end(); ++it)
		last = static_cast<C2DMessageString *>(*it); /* ELF: no type test */

	if (last != NULL)
		return const_cast<char *>(last->m_text.c_str());

	return const_cast<char *>("");
}

