/* Add_Message's shared part (inline twice in the ELF): a message wider than m_maxlength (less
 * both X margins) and holding a space is cut at the last space that fits, the rest (from that
 * space) is queued by a recursive call; else the queue starts its descent. Returns the rest or
 * NULL. */
const char *C2DMessage_Q::QueueMessage(C2DMessageString *msg, const char *text)
{
	C2DString probe;
	probe.SetString(text);
	probe.m_scale = m_scale;
	probe.SetFont(m_font);
	probe.UpdatePos();
	strlen(text); /* ELF: result unused */
	f32 maxlength = m_maxlength;
	s32 limit = (s32)(maxlength - (f32)(m_XMargin * 2));

	if (maxlength != 0.0f && !(probe.m_length <= (f32)limit) && strstr(text, " ") != NULL)
	{
		probe.SetString("");
		probe.UpdatePos();
		s32 i = 0;

		while (probe.m_length < (f32)limit && text[i] != '\0')
		{
			probe.AddCharacter(text[i]);
			probe.UpdatePos();
			i++;
		}

		while (text[i] != ' ') /* ELF: no lower bound (the text holds a space) */
			i--;

		char first[512];
		strncpy(first, text, i);
		first[i] = '\0';
		msg->SetString(first);
		msg->UpdatePos();
		push_back(msg);
		return text[i] != '\0' ? text + i : NULL;
	}

	m_target_top = (f32)m_top;
	m_moveTime = 0.0f;
	m_displayTime = 0.0f;
	m_Distance = m_target_top - (f32)m_cur_top;
	m_displayTime = 0.0f;
	push_back(msg);
	return NULL;
}

/* @socom-skeleton stub Add_Message__12C2DMessage_QFPCci */
void C2DMessage_Q::Add_Message(const char *text, int time)
{
	/* 0x2004b0 (zAnimMessageTick, ammo, subtitles...): with a font and the queue enabled a new
	 * message in the queue's colour (red, green, blue), opacity 100, shown for time seconds (0:
	 * the queue's fade time), typed at the queue's TtySpeed. */
	if (m_font == NULL || !m_bEnabled)
		return;

	C2DMessageString *msg = new C2DMessageString;

	if (time == 0)
		time = (s32)m_transstep;

	msg->SetString(text);
	msg->m_scale = m_scale;
	msg->SetFont(m_font);
	msg->m_color.x = (f32)m_red;
	msg->m_color.y = (f32)m_green;
	msg->m_color.z = (f32)m_blue;
	msg->m_time = (f32)time;
	msg->SetTrans(100.0f);
	msg->UpdatePos();
	msg->m_ttySpeed = m_TtySpeed;
	const char *rest = QueueMessage(msg, text);

	if (rest != NULL)
		Add_Message(rest, time);
}

/* @socom-skeleton stub Add_Message__12C2DMessage_QFPCciii */
void C2DMessage_Q::Add_Message(const char *text, int red, int green, int blue)
{
	/* 0x200130 (MESSAGE with a colour, OnDeath, remote messages): as Add_Message(text, time)
	 * with the given colour and the queue's fade time */
	if (m_font == NULL || !m_bEnabled)
		return;

	C2DMessageString *msg = new C2DMessageString;
	msg->SetString(text);
	msg->m_scale = m_scale;
	msg->SetFont(m_font);
	msg->m_color.x = (f32)red;
	msg->m_color.y = (f32)green;
	msg->m_color.z = (f32)blue;
	msg->m_time = m_transstep;
	msg->SetTrans(100.0f);
	msg->UpdatePos();
	msg->m_ttySpeed = m_TtySpeed;
	const char *rest = QueueMessage(msg, text);

	if (rest != NULL)
		Add_Message(rest, red, green, blue);
}

/* @socom-skeleton body ScrollUp__12C2DMessage_QFv */
void C2DMessage_Q::ScrollUp()
{
    m_target_top = -m_YMargin;
    m_Distance = -m_YMargin - m_cur_top;
    m_moveTime = 0;
}

/* @socom-skeleton stub Tick__12C2DMessage_QFf */
void C2DMessage_Q::Tick(float dT)
{
	/* 0x1ffd20 (CHUD::HudTick): while on, every message ticks; a descending queue holds at
	 * m_top for the fade time after the last message, then slides back up (1 s); a
	 * non-descending one stays at m_top. Over m_maxsize the oldest message goes; a message
	 * 0.5 s past its time is removed, and the last one leaving starts the slide up. */
	if (!IsOn())
		return;

	for (iterator it = begin(); it != end(); ++it)
		(*it)->Tick(dT);

	m_moveTime += dT;
	m_displayTime += dT;

	if (!m_descends)
	{
		m_cur_top = m_top;
	}
	else if (!(m_displayTime <= m_transstep) && m_cur_top == m_top)
	{
		m_target_top = (f32)-m_YMargin;
		m_Distance = m_target_top - (f32)m_cur_top;
		m_moveTime = 0.0f;
		m_displayTime = 0.0f;
	}
	else if (m_moveTime <= 1.0f)
	{
		m_cur_top = (s32)(m_target_top - m_Distance * (1.0f - m_moveTime));
	}
	else
	{
		m_cur_top = (s32)m_target_top;
	}

	if ((u32)m_maxsize < (u32)size())
	{
		C2D *oldest = front();
		erase(begin());

		if (oldest != NULL)
			delete oldest;
	}

	for (iterator it = begin(); it != end();)
	{
		C2DMessageString *msg = dynamic_cast<C2DMessageString *>(*it);
		iterator next = it;
		++next;

		if (msg != NULL && !(msg->m_elapsed <= msg->m_time + 0.5f))
		{
			next = erase(it);
			delete msg;

			if (empty())
			{
				m_target_top = (f32)-m_YMargin;
				m_Distance = m_target_top - (f32)m_cur_top;
				m_moveTime = 0.0f;
			}
		}

		it = next;
	}
}

/* @socom-skeleton stub Draw__12C2DMessage_QFPQ23zdb7CCamera */
void C2DMessage_Q::Draw(zdb::CCamera *camera)
{
	/* 0x1ff9a0: while on, the two background halves around the queue (left-aligned from
	 * m_left, or centred on it), then the messages newest first upwards from m_cur_top by
	 * m_spacing (centred ones by half their length; positions x16), each Update'd with its
	 * opacity kept, then drawn (C2D::Draw) */
	if (!IsOn())
		return;

	s32 bottom = m_cur_top + m_YMargin;
	s32 top = m_cur_top - m_maxsize * m_spacing - m_YMargin;

	if (!m_centered)
	{
		m_background1.SetPos(m_left - m_XMargin, top, (s32)((f32)m_left + m_maxlength / 2.0f), bottom);
		m_background2.SetPos((s32)((f32)m_left + m_maxlength / 2.0f), top,
			(s32)((f32)m_XMargin + ((f32)m_left + m_maxlength)), bottom);
	}
	else
	{
		m_background1.SetPos((s32)((f32)m_left - m_maxlength / 2.0f - (f32)m_XMargin), top, m_left, bottom);
		m_background2.SetPos(m_left, top, (s32)((f32)m_XMargin + ((f32)m_left + m_maxlength / 2.0f)), bottom);
	}

	m_background1.Draw(camera);
	m_background2.Draw(camera);
	s32 index = 0;

	for (reverse_iterator it = rbegin(); it != rend(); ++it, index++)
	{
		C2DString *msg = static_cast<C2DString *>(*it); /* ELF: no type test */
		s32 y = m_cur_top - index * m_spacing;

		if (!m_centered)
			msg->m_pos.x = m_left * 16;
		else
			msg->m_pos.x = (s32)((f32)m_left - msg->m_length / 2.0f) * 16;

		msg->m_pos.y = y * 16;
		f32 trans = msg->m_color.w;
		msg->Update();
		msg->SetTrans(trans);
	}

	C2D::Draw(camera);
}
